task count_Rotation(s: seq, n: int) returns (r: int)
  requires n >= 0
  requires n <= len(s)
  ensures r >= 0
  ensures r <= n
  ensures r == 0 ==> (forall i in [0, n) . s[i] == s[0] + i)
  ensures r == n ==> (forall i in [0, n) . s[i] == s[n - 1] + i)
  ensures r == k ==> (forall i in [0, k) . s[i] == s[k] + i) and (forall i in [k, n) . s[i] == s[k] + (i - k))
